var quickReactions = ["👍","❤️","😂","😮","😢","🙏"];
var extraReactions = ["✅","👀","👏","🎉","💡","🤔","❓","🙋"];
var reactions = quickReactions.concat(extraReactions);
var reactionLabels = {"✅":"Done","👀":"Taking a look","👏":"Well done","🎉":"Celebrate","💡":"Idea","🤔":"Thinking","❓":"Question","🙋":"I can help"};
function choices(category,query) {
    const term = query.trim().toLowerCase();
    const groups = term ? categories : [categories[category] || categories[0]];
    const result = [];
    for (const group of groups) {
        for (const item of group.emojis) {
            if (!term || item.name.toLowerCase().includes(term)) result.push(item);
            if (result.length === 250) return result;
        }
    }
    return result;
}
function applyReaction(state,emoji,from,on) {
    if (!reactions.includes(emoji)) return;
    const users = state[emoji] || [];
    const index = users.indexOf(from);
    if (on && index < 0) users.push(from);
    if (!on && index >= 0) users.splice(index,1);
    state[emoji] = users;
}
